// Bespoke Open-Source Brand Fonts: Syne (Bold Display) and Space Grotesk (Medium Geometric Sans)
// Embedded as base64 so Satori/workers-og renders authentic bespoke typography
// without external runtime fetch dependencies.

const SYNE_BOLD_B64 =
  "";

const SPACE_GROTESK_B64 =
  "";

function decode(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

export const FONT_DISPLAY = decode(SYNE_BOLD_B64);
export const FONT_SANS = decode(SPACE_GROTESK_B64);

// Backward-compatibility aliases
export const FONT_BOLD = FONT_DISPLAY;
export const FONT_REGULAR = FONT_SANS;
